          <div className="requests-container">
            <div className="requests-header">
              <div>Method</div>
              <div>Status</div>
              <div>Domain</div>
              <div>Path</div>
              <div>Time</div>
              <div className="text-right">Duration</div>
              <div className="text-right">Size</div>
            </div>

